def causal_mask(length, valid_length=None):
    if valid_length is None:
        valid_length = length
    if length < 0 or not 0 <= valid_length <= length:
        raise ValueError("非法序列长度")
    return [[j > i or j >= valid_length for j in range(length)]
            for i in range(length)]

